@SpringBootTest
public class ContactViewTest extends SpringBrowserlessTest {

    @Test
    public void testContactViewLoads() {
        navigate("contact");
        var heading = $(H1.class).first();
        assertEquals("Contact", heading.getText());
    }

    @Test
    public void testComponentsPresent() {
        navigate("contact");

        var nameField = $(TextField.class).all().stream()
