    public void testSendWithoutName() {
        navigate("contact");

        var nameField = $(TextField.class).all().stream()
                .filter(f -> "Name".equals(f.getLabel()))
                .findFirst()
                .orElseThrow();

        var button = $(Button.class).first();

        nameField.setValue("");
        button.click();

        assertTrue(nameField.isInvalid());
    }

    @Test
    public void testSendWithName() {
        navigate("contact");

        var nameField = $(TextField.class).all().stream()
                .filter(f -> "Name".equals(f.getLabel()))
                .findFirst()
                .orElseThrow();

        var emailField = $(EmailField.class).first();
        var messageField = $(TextArea.class).first();
        var button = $(Button.class).first();

        nameField.setValue("John Doe");
        emailField.setValue("john@example.com");
        messageField.setValue("Test message");

        button.click();

        assertFalse(nameField.isInvalid());
        assertTrue(nameField.isEmpty());
        assertTrue(emailField.isEmpty());
        assertTrue(messageField.isEmpty());
    }
}
